import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    idx = 0
    L = int(data[idx])
    W = int(data[idx+1])
    H = int(data[idx+2])
    idx += 3

    grid = []
    for l in range(L):
        layer = []
        for w in range(W):
            row = []
            for h in range(H):
                row.append(int(data[idx]))
                idx += 1
            layer.append(row)
        grid.append(layer)

    if L == 0 or W == 0 or H == 0:
        print(-1)
        return

    max_sum = -float('inf')

    for l1 in range(L):
        for l2 in range(l1, L):
            for w1 in range(W):
                for w2 in range(w1, W):
                    current_sum = 0
                    for h in range(H):
                        for l in range(l1, l2 + 1):
                            for w in range(w1, w2 + 1):
                                current_sum += grid[l][w][h]
                    max_sum = max(max_sum, current_sum)

    if max_sum == -float('inf'):
        print(-1)
    else:
        print(int(max_sum))

if __name__ == "__main__":
    main()
